(()=>{
const body=document.querySelector('.review-body'),figure=body.querySelector('figure'),stars=document.getElementById('review-stars'),text=document.getElementById('review-text'),author=document.getElementById('review-author'),count=document.getElementById('review-count'),motion=matchMedia('(prefers-reduced-motion: reduce)');
const stage=document.createElement('div');stage.className='review-motion-stage';const slide=document.createElement('div');slide.className='review-motion-slide';figure.before(stage);stage.append(slide);slide.append(figure,stars);body.setAttribute('role','region');body.setAttribute('aria-roledescription','carrusel');body.setAttribute('aria-label','Reseñas de clientes');body.tabIndex=0;
let reviews=[],index=0,busy=false,pending=0;
function render(){const review=reviews[index];text.textContent=review.text||'Valoración sin comentario.';author.textContent=review.author+' · Google ';author.append(corteIcon('ne'));author.href=review.source;stars.replaceChildren(...Array.from({length:5},(_,i)=>{const star=corteIcon('star');if(i>=review.rating)star.setAttribute('fill','none');return star}));stars.setAttribute('aria-label',review.rating+' estrellas');count.textContent=String(index+1).padStart(2,'0')+' / '+String(reviews.length).padStart(2,'0')}
async function move(direction){if(reviews.length<2)return;if(busy){pending+=direction;return}busy=true;const animate=!motion.matches&&typeof slide.animate==='function';let out,enter;try{if(animate){stage.style.minHeight=stage.offsetHeight+'px';out=slide.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(-10px)'}],{duration:300,easing:'ease-out',fill:'forwards'});await out.finished}index=(index+direction%reviews.length+reviews.length)%reviews.length;render();if(animate){enter=slide.animate([{opacity:0,transform:'translateY(14px)'},{opacity:1,transform:'translateY(0)'}],{duration:300,easing:'ease-out',fill:'forwards'});out.cancel();await enter.finished;enter.cancel()}}catch{out?.cancel();enter?.cancel()}finally{stage.style.minHeight='';busy=false;if(pending){const next=pending;pending=0;move(next)}}}
document.getElementById('review-prev').addEventListener('click',()=>move(-1));document.getElementById('review-next').addEventListener('click',()=>move(1));body.addEventListener('keydown',event=>{if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();move(event.key==='ArrowRight'?1:-1)}});let touch=null;body.addEventListener('touchstart',event=>{if(event.touches.length===1)touch={x:event.touches[0].clientX,y:event.touches[0].clientY};else touch=null},{passive:true});body.addEventListener('touchend',event=>{if(!touch)return;const dx=event.changedTouches[0].clientX-touch.x,dy=event.changedTouches[0].clientY-touch.y;touch=null;if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy)*1.25)move(dx<0?1:-1)},{passive:true});body.addEventListener('touchcancel',()=>{touch=null},{passive:true});
fetch('assets/reviews.json').then(response=>{if(!response.ok)throw Error('reviews');return response.json()}).then(data=>{reviews=data;if(reviews.length)render()}).catch(()=>{});
})();
